"""Backtest results: per timeframe, which strategies' BUY / SELL calls were right."""

from __future__ import annotations

from datetime import datetime
from typing import Any, Literal

from pydantic import BaseModel, Field

#: ``builtin`` / ``rule``: strategies in the pool. ``template`` / ``llm``: new rule
#: candidates generated by the backtest (not in the pool until saved).
StrategyOrigin = Literal["builtin", "rule", "template", "llm"]


class HitStats(BaseModel):
    """Directional hit rate of one strategy over a set of candles."""

    signals: int = 0  # BUY + SELL candles scored
    buys: int = 0
    sells: int = 0
    sideways: int = 0
    hits: int = 0
    buy_hits: int = 0
    sell_hits: int = 0
    episodes: int = 0  # distinct runs of the same BUY / SELL signal
    hit_rate: float | None = None
    buy_hit_rate: float | None = None
    sell_hit_rate: float | None = None
    #: Wilson 95% lower bound of the hit rate: the ranking score (small samples rank low).
    score: float = 0.0
    #: Mean move in the signalled direction, in pips (positive = price went the right way).
    avg_move_pips: float | None = None


class LLMCheck(BaseModel):
    """The live LLM decision replayed on a sample of a strategy's own BUY / SELL candles."""

    samples: int = 0
    llm_signals: int = 0  # the LLM said BUY or SELL
    llm_hits: int = 0
    llm_hit_rate: float | None = None
    rule_hit_rate: float | None = None  # the strategy's rule on the same candles
    agreement: float | None = None  # share of samples where the LLM matched the rule
    abstained: int = 0  # the LLM said SIDEWAYS
    errors: int = 0
    providers: list[str] = Field(default_factory=list)
    cost_usd: float | None = None


class StrategyScore(BaseModel):
    name: str
    display_name: str
    origin: StrategyOrigin
    category: str
    description: str = ""
    params: dict[str, Any] = Field(default_factory=dict)
    stats: HitStats = Field(default_factory=HitStats)  # the whole backtest period
    train: HitStats | None = None  # first half (candidates are chosen on it)
    validation: HitStats | None = None  # second half (candidates are judged on it)
    ranked: bool = False  # enough signals to compete
    llm_check: LLMCheck | None = None
    #: Rule spec of a generated candidate (what "Save as strategy" writes).
    rule: dict[str, Any] | None = None
    error: str | None = None


class SkippedStrategy(BaseModel):
    name: str
    display_name: str
    reason: str


class TimeframeBacktest(BaseModel):
    timeframe: str
    candles: int = 0  # candles in the scored period
    start: datetime | None = None
    end: datetime | None = None
    horizon_bars: int = 0
    best: str | None = None  # best ranked pool strategy
    best_candidate: str | None = None  # best generated rule that held up on validation
    strategies: list[StrategyScore] = Field(default_factory=list)
    candidates: list[StrategyScore] = Field(default_factory=list)
    skipped: list[SkippedStrategy] = Field(default_factory=list)
    notes: list[str] = Field(default_factory=list)
    error: str | None = None


class BacktestResult(BaseModel):
    run_id: str
    instrument: str
    generated_at: datetime
    duration_ms: int
    days: float
    window: int  # candles each replayed signal sees (as live)
    pip_size: float
    spread_pips: float | None = None  # a hit must beat this move
    timeframes: dict[str, TimeframeBacktest]
    llm_cost_usd: float | None = None
    notes: list[str] = Field(default_factory=list)
